selector_to_html = {"a[href=\"../getting_started/install.html#metax\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">MetaX<a class=\"headerlink\" href=\"#metax\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#id1\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Step 1: Pull Image and Create Container<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h3><p>Follow the <a class=\"reference internal\" href=\"../getting_started/install.html#metax\"><span class=\"std std-ref\">MetaX Docker setup</span></a> in Quick Setup.</p>", "a[href=\"#id2\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Step 2: Prepare Data and Model<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#step-5-modify-script-and-run\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Step 5: Modify Script and Run<a class=\"headerlink\" href=\"#step-5-modify-script-and-run\" title=\"Link to this heading\">#</a></h3><p>Based on <code class=\"docutils literal notranslate\"><span class=\"pre\">examples/grpo_trainer/run_qwen3-0.6b_fl.sh</span></code>, modify model/data/FlagCX paths according to your actual setup (all paths below assume <code class=\"docutils literal notranslate\"><span class=\"pre\">/workspace</span></code> from the steps above):</p>", "a[href=\"#id4\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Step 4: Install verl-FL<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#id3\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Step 3: Install FlagOS Software Stack<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h3><p><strong>3.1 Install FlagCX (Required)</strong></p>", "a[href=\"#end-to-end-use-case-grpo-training-with-verl-fl\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">End-to-End Use Case: GRPO Training with verl-FL<a class=\"headerlink\" href=\"#end-to-end-use-case-grpo-training-with-verl-fl\" title=\"Link to this heading\">#</a></h1><p>This guide provides step-by-step instructions for running end-to-end GRPO training of Qwen3-0.6B on the GSM8K dataset across different hardware platforms using verl-FL.</p>", "a[href=\"#nvidia-e2e-grpo-training\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">NVIDIA E2E GRPO Training<a class=\"headerlink\" href=\"#nvidia-e2e-grpo-training\" title=\"Link to this heading\">#</a></h2><p>End-to-end GRPO training test on NVIDIA GPU environment. Model: Qwen3-0.6B, Dataset: GSM8K.</p>", "a[href=\"#step-3-install-flagos-software-stack\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Step 3: Install FlagOS Software Stack<a class=\"headerlink\" href=\"#step-3-install-flagos-software-stack\" title=\"Link to this heading\">#</a></h3><p><strong>3.1 Install FlagCX (Required)</strong></p>", "a[href=\"#id5\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Step 5: Modify Script and Run<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h3><p>Based on <code class=\"docutils literal notranslate\"><span class=\"pre\">examples/grpo_trainer/run_qwen3-0.6b_fl.sh</span></code>, modify model/data/FlagCX paths according to your actual setup (all paths below assume <code class=\"docutils literal notranslate\"><span class=\"pre\">/workspace</span></code> from the steps above):</p>", "a[href=\"#metax-e2e-grpo-training\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">MetaX E2E GRPO Training<a class=\"headerlink\" href=\"#metax-e2e-grpo-training\" title=\"Link to this heading\">#</a></h2><p>End-to-end GRPO training test on MetaX C500 environment. Model: Qwen3-0.6B, Dataset: GSM8K.</p>", "a[href=\"#step-1-pull-image-and-create-container\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Step 1: Pull Image and Create Container<a class=\"headerlink\" href=\"#step-1-pull-image-and-create-container\" title=\"Link to this heading\">#</a></h3><p>Follow the <a class=\"reference internal\" href=\"../getting_started/install.html#nvidia\"><span class=\"std std-ref\">NVIDIA Docker setup</span></a> in Quick Setup.</p>", "a[href=\"#step-2-prepare-data-and-model\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Step 2: Prepare Data and Model<a class=\"headerlink\" href=\"#step-2-prepare-data-and-model\" title=\"Link to this heading\">#</a></h3>", "a[href=\"../getting_started/install.html#nvidia\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">NVIDIA<a class=\"headerlink\" href=\"#nvidia\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#step-4-install-verl-fl\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Step 4: Install verl-FL<a class=\"headerlink\" href=\"#step-4-install-verl-fl\" title=\"Link to this heading\">#</a></h3>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
